<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$id=max(1,(int)($_GET['id']??$_POST['id']??0));$s=$db->prepare("SELECT d.*,cr.libelle categorie,c.type_client,c.nom,c.prenom,c.raison_sociale,c.numero_client FROM demandes_devis d JOIN categories_risque cr ON cr.id=d.categorie_id JOIN clients c ON c.id=d.client_id WHERE d.id=?");$s->execute([$id]);$demande=$s->fetch()?:exit('Demande introuvable.');$s=$db->prepare("SELECT * FROM questions WHERE categorie_id=? AND statut='active' ORDER BY ordre_affichage,id");$s->execute([$demande['categorie_id']]);$questions=$s->fetchAll();$s=$db->prepare('SELECT question_id,valeur_reponse FROM reponses_questionnaire WHERE demande_id=?');$s->execute([$id]);$answers=[];foreach($s->fetchAll() as $r)$answers[(int)$r['question_id']]=$r['valeur_reponse'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach($questions as $q){$value=trim((string)($_POST['reponse'][$q['id']]??''));if($q['obligatoire']&&$value==='')$errors[]='Réponse requise : '.$q['libelle'];if($value!==''&&$q['type_reponse']==='nombre'&&!is_numeric($value))$errors[]='Valeur numérique attendue : '.$q['libelle'];$answers[(int)$q['id']]=$value;}if(!$errors){$db->beginTransaction();$up=$db->prepare('INSERT INTO reponses_questionnaire(demande_id,question_id,valeur_reponse) VALUES(?,?,?) ON DUPLICATE KEY UPDATE valeur_reponse=VALUES(valeur_reponse)');foreach($questions as $q){$value=$answers[(int)$q['id']]??'';if($value!=='')$up->execute([$id,$q['id'],$value]);}$db->prepare("UPDATE demandes_devis SET statut='complete' WHERE id=? AND statut='brouillon'")->execute([$id]);$db->commit();audit('QUESTIONNAIRE_COMPLETE','demande_devis',$id);flash('success','Questionnaire enregistré. La demande est prête pour la comparaison.');redirect('demandes/index.php');}}
$client=$demande['type_client']==='entreprise'?$demande['raison_sociale']:trim($demande['prenom'].' '.$demande['nom']);$title='Questionnaire';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><div><h1 class="h3">Questionnaire <?= e($demande['categorie']) ?></h1><p class="text-secondary mb-0"><?= e($demande['numero_demande'].' · '.$demande['numero_client'].' · '.$client) ?></p></div><a class="btn btn-outline-secondary" href="index.php">Retour</a></div><?php if($errors): ?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $e2): ?><li><?= e($e2) ?></li><?php endforeach ?></ul></div><?php endif; ?><?php if(!$questions): ?><div class="alert alert-warning">Aucune question active n’est configurée pour cette branche.</div><?php else: ?><form method="post" class="card card-body"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><div class="question-list"><?php foreach($questions as $i=>$q): $value=$answers[(int)$q['id']]??'';?><div class="question-item"><label class="form-label fw-semibold"><?= $i+1 ?>. <?= e($q['libelle']) ?> <?= $q['obligatoire']?'<span class="text-danger">*</span>':'' ?></label><?php if($q['type_reponse']==='liste'): $opts=json_decode((string)$q['options_json'],true)?:[];?><select class="form-select" name="reponse[<?= $q['id'] ?>]" <?= $q['obligatoire']?'required':'' ?>><option value="">Sélectionner</option><?php foreach($opts as $o): ?><option value="<?= e((string)$o) ?>" <?= $value===(string)$o?'selected':'' ?>><?= e((string)$o) ?></option><?php endforeach ?></select><?php elseif($q['type_reponse']==='booleen'): ?><select class="form-select" name="reponse[<?= $q['id'] ?>]" <?= $q['obligatoire']?'required':'' ?>><option value="">Sélectionner</option><option value="oui" <?= $value==='oui'?'selected':'' ?>>Oui</option><option value="non" <?= $value==='non'?'selected':'' ?>>Non</option></select><?php else: ?><input class="form-control" type="<?= $q['type_reponse']==='nombre'?'number':($q['type_reponse']==='date'?'date':'text') ?>" name="reponse[<?= $q['id'] ?>]" value="<?= e($value) ?>" <?= $q['obligatoire']?'required':'' ?>><?php endif; ?></div><?php endforeach ?></div><div class="text-end mt-4"><button class="btn btn-primary">Valider le questionnaire</button></div></form><?php endif; ?></div><?php require __DIR__.'/../../includes/footer.php'; ?>
